.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-n { cursor: n-resize; left: 50%; top: 0px; transform: translateX(-50%); }
.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-ne { cursor: ne-resize; right: 0px; top: 0px; }
.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-e { cursor: e-resize; right: 0px; top: 50%; transform: translateY(-50%); }
.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-se { bottom: 0px; cursor: se-resize; right: 0px; }
.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-s { bottom: 0px; cursor: s-resize; left: 50%; transform: translateX(-50%); }
.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-sw { bottom: 0px; cursor: sw-resize; left: 0px; }
.ehfuse-editor-wrapper .ehfuse-image-resize-overlay .ehfuse-resize-handle-w { cursor: w-resize; left: 0px; top: 50%; transform: translateY(-50%); }
.ehfuse-editor-wrapper .ehfuse-editor-content img { cursor: pointer; height: auto; max-width: 100%; outline: none; }
.ehfuse-editor-wrapper .ehfuse-editor-content img::selection { background: transparent; }
.ehfuse-editor-wrapper .ehfuse-editor-content ::selection { background: rgba(0, 102, 204, 0.2); }
body.ehfuse-resizing { user-select: none; }
body.ehfuse-resizing, body.ehfuse-resizing * { cursor: inherit !important; }

